class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        root = {}
        for w in words:
            cur = root
            for c in w:
                cur = cur.setdefault(c, {})
        n = len(target)
        f = [0] * n
        for i in range(n):
            cur, L = root, 0
            while i + L < n and target[i + L] in cur:
                cur = cur[target[i + L]]
                L += 1
            f[i] = L
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(n):
            if dp[i] == INF:
                continue
            v = dp[i] + 1
            for L in range(1, f[i] + 1):
                if v < dp[i + L]:
                    dp[i + L] = v
        return dp[n] if dp[n] < INF else -1

