class Solution {
public:
    int minValidStrings(vector<string>& words, string target) {
        vector<array<int,26>> trie(1);
        trie[0].fill(-1);
        for (auto& w : words) {
            int cur = 0;
            for (char c : w) {
                int j = c - 'a';
                if (trie[cur][j] < 0) {
                    trie[cur][j] = trie.size();
                    trie.push_back({});
                    trie.back().fill(-1);
                }
                cur = trie[cur][j];
            }
        }
        int n = target.size();
        vector<int> f(n);
        for (int i = 0; i < n; i++) {
            int cur = 0, L = 0;
            while (i + L < n && trie[cur][target[i+L]-'a'] >= 0) {
                cur = trie[cur][target[i+L]-'a'];
                L++;
            }
            f[i] = L;
        }
        const int INF = INT_MAX / 2;
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == INF) continue;
            for (int L = 1; L <= f[i]; L++) dp[i + L] = min(dp[i + L], dp[i] + 1);
        }
        return dp[n] >= INF ? -1 : dp[n];
    }
};

