class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        MOD = (1 << 61) - 1
        B = 1000003
        pref = set()
        for w in words:
            h = 0
            for c in w:
                h = (h * B + ord(c)) % MOD
                pref.add(h)
        n = len(target)
        f = [0] * n
        for i in range(n):
            h, L = 0, 0
            while i + L < n:
                h = (h * B + ord(target[i + L])) % MOD
                if h not in pref:
                    break
                L += 1
            f[i] = L
        INF = float('inf')
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(n):
            if dp[i] == INF:
                continue
            v = dp[i] + 1
            for L in range(1, f[i] + 1):
                if v < dp[i + L]:
                    dp[i + L] = v
        return dp[n] if dp[n] < INF else -1

