class Solution {
public:
    int minValidStrings(vector<string>& words, string target) {
        const unsigned long long M1 = 1000000007ULL, B1 = 131, M2 = 998244353ULL, B2 = 137;
        set<pair<unsigned long long, unsigned long long>> pref;
        for (auto& w : words) {
            unsigned long long h1 = 0, h2 = 0;
            for (char c : w) {
                h1 = (h1 * B1 + c) % M1;
                h2 = (h2 * B2 + c) % M2;
                pref.insert({h1, h2});
            }
        }
        int n = target.size();
        vector<int> f(n);
        for (int i = 0; i < n; i++) {
            unsigned long long h1 = 0, h2 = 0;
            int L = 0;
            while (i + L < n) {
                h1 = (h1 * B1 + target[i+L]) % M1;
                h2 = (h2 * B2 + target[i+L]) % M2;
                if (!pref.count({h1, h2})) break;
                L++;
            }
            f[i] = L;
        }
        const int INF = INT_MAX / 2;
        vector<int> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] == INF) continue;
            for (int L = 1; L <= f[i]; L++) dp[i + L] = min(dp[i + L], dp[i] + 1);
        }
        return dp[n] >= INF ? -1 : dp[n];
    }
};

