    let h1 = 0, h2 = 0;
    for (const ch of w) {
      const c = ch.charCodeAt(0);
      h1 = (h1 * B1 + c) % M1;
      h2 = (h2 * B2 + c) % M2;
      pref.add(h1 + ',' + h2);
    }
