      const c = target.charCodeAt(i + L);
      h1 = (h1 * B1 + c) % M1;
      h2 = (h2 * B2 + c) % M2;
      if (!pref.has(h1 + ',' + h2)) break;
      L++;
    }
    f[i] = L;
  }
  const INF = Infinity, dp = new Array(n + 1).fill(INF);
  dp[0] = 0;
  for (let i = 0; i < n; i++) {
    if (dp[i] === INF) continue;
